import { ServicePluginDefinition } from '@wix/sdk-types';
import {
  Context,
  CalculatePriceRequest,
  CalculatePriceResponse,
} from './service-plugins-types.js';
import { transformSDKFloatToRESTFloat } from '@wix/sdk-runtime/transformations/float';
import { transformRESTFloatToSDKFloat } from '@wix/sdk-runtime/transformations/float';
import { transformRESTTimestampToSDKTimestamp } from '@wix/sdk-runtime/transformations/timestamp';
import { transformPaths } from '@wix/sdk-runtime/transformations/transform-paths';
import {
  renameKeysFromSDKRequestToRESTRequest,
  renameKeysFromRESTResponseToSDKResponse,
} from '@wix/sdk-runtime/rename-all-nested-keys';

export interface CalculatePriceEnvelope {
  request: CalculatePriceRequest;
  metadata: Context;
}

export const provideHandlers = ServicePluginDefinition<{
  /**
   *
   * The Custom Pricing extension lets site owners add custom pricing
   * to bookings on the site. The custom pricing is calculated and used as the
   * basis for the price when checking out the booking, overriding the standard
   * Bookings pricing logic.
   *
   * Parameter: An `Options` object, which contains the booking.
   * Response: An object that contains the `calculatedPrice`:
   * ```json
   * {
   * "calculatedPrice": 100
   * }
   * ``` */
  calculatePrice(
    payload: CalculatePriceEnvelope
  ): CalculatePriceResponse | Promise<CalculatePriceResponse>;
}>('BOOKINGS_PRICING_PROVIDER', [
  {
    name: 'calculatePrice',
    primaryHttpMappingPath: '/v1/calculate-price',
    transformations: {
      toREST: (payload: any) => {
        const toRestResponse = transformPaths(payload, [
          {
            transformFn: transformSDKFloatToRESTFloat,
            paths: [
              { path: 'calculatedPrice' },
              { path: 'deposit' },
              { path: 'bookingLineItems.pricePerParticipant' },
              { path: 'bookingLineItems.serviceChoices.pricePerParticipant' },
            ],
          },
        ]);

        return renameKeysFromSDKRequestToRESTRequest(toRestResponse);
      },
      fromREST: (payload: any) => {
        const fromRestRequest = transformPaths(payload, [
          {
            transformFn: transformRESTTimestampToSDKTimestamp,
            paths: [
              { path: 'request.booking.createdDate' },
              { path: 'request.booking.startDate' },
              { path: 'request.booking.endDate' },
              { path: 'request.booking.updatedDate' },
              { path: 'request.booking.canceledDate' },
            ],
          },
          {
            transformFn: transformRESTFloatToSDKFloat,
            paths: [
              {
                path: 'request.booking.contactDetails.fullAddress.geocode.latitude',
              },
              {
                path: 'request.booking.contactDetails.fullAddress.geocode.longitude',
              },
            ],
          },
        ]);

        return renameKeysFromRESTResponseToSDKResponse(fromRestRequest);
      },
    },
  },
]);
